import json
from app.services.llm import ask_llm, extract_json
SYSTEM='''You are a senior software developer. Generate a small runnable educational project. Return ONLY JSON: {"files":[{"path":"relative/path","content":"complete file content"}]}. Include tests and README. Do not include secrets, destructive commands, network exfiltration, shell scripts or security bypasses. Use relative paths only.'''

def demo_files():
    return [
      {'path':'main.py','content':'''"""Simple student record manager backed by JSON."""\nimport json\nfrom pathlib import Path\nDATA_FILE=Path(__file__).with_name("students.json")\ndef load_students():\n    return json.loads(DATA_FILE.read_text(encoding="utf-8")) if DATA_FILE.exists() else []\ndef save_students(students):\n    DATA_FILE.write_text(json.dumps(students,indent=2),encoding="utf-8")\ndef add_student(name,roll_no):\n    students=load_students()\n    if any(s["roll_no"]==roll_no for s in students): raise ValueError("Roll number already exists")\n    students.append({"name":name,"roll_no":roll_no}); save_students(students)\ndef list_students(): return load_students()\nif __name__=="__main__":\n    add_student("Aarav Sharma","101")\n    print("Students:",list_students())\n'''},
      {'path':'test_main.py','content':'''import tempfile,unittest\nfrom pathlib import Path\nimport main\nclass StudentTests(unittest.TestCase):\n    def setUp(self):\n        self.temp=tempfile.TemporaryDirectory(); main.DATA_FILE=Path(self.temp.name)/"students.json"\n    def tearDown(self): self.temp.cleanup()\n    def test_add_and_list(self):\n        main.add_student("Aarav","101"); self.assertEqual(main.list_students()[0]["name"],"Aarav")\n    def test_duplicate_roll(self):\n        main.add_student("Aarav","101")\n        with self.assertRaises(ValueError): main.add_student("Riya","101")\nif __name__=="__main__": unittest.main()\n'''},
      {'path':'README.md','content':'# Student Record Manager\n\nDemo Python project generated by PS02.\n\nRun: `python main.py`\n\nTest: `python -m unittest -v`\n'}]

async def generate_files(prompt,plan):
    try:
        data=extract_json(await ask_llm(SYSTEM,json.dumps({'user_request':prompt,'plan':plan},ensure_ascii=False)))
        result=data.get('files')
        if not isinstance(result,list) or not result: raise ValueError('No files generated')
        for item in result:
            if not isinstance(item.get('path'),str) or not isinstance(item.get('content'),str): raise ValueError('Invalid file entry')
        return result,'llm'
    except Exception: return demo_files(),'demo'
